<?php require __DIR__.'/bootstrap.php';
try{admin_user();$action=$_GET['action']??'';$pdo=db();if($action==='dashboard'){ $counts=[];foreach(['products','categories','orders','complaints','coupons','users'] as $t){$counts[$t]=(int)$pdo->query("SELECT COUNT(*) FROM `$t`")->fetchColumn();}ok($counts);}if($action==='users'){ok($pdo->query('SELECT u.id,u.email,u.role,p.full_name,p.phone,p.address,u.created_at,u.updated_at FROM users u LEFT JOIN profiles p ON p.id=u.id ORDER BY u.created_at DESC')->fetchAll());}if($action==='update-user'){ $id=(string)($p['id']??''); $role=(string)($p['role']??'customer'); if(!$id || !in_array($role,['customer','admin'],true)) fail('Invalid user update'); $pdo->beginTransaction(); try { $pdo->prepare('UPDATE users SET role=? WHERE id=?')->execute([$role,$id]); $pdo->prepare('UPDATE profiles SET role=? WHERE id=?')->execute([$role,$id]); $pdo->commit(); ok(['id'=>$id,'role'=>$role]); } catch(Throwable $e){ if($pdo->inTransaction())$pdo->rollBack(); throw $e; } }if($action==='wishlist-summary'){ $sql='SELECT product_id,COUNT(*) AS count FROM wishlists GROUP BY product_id ORDER BY count DESC'; ok($pdo->query($sql)->fetchAll()); }if($action==='products'){ok($pdo->query('SELECT * FROM products ORDER BY sort_order,created_at DESC')->fetchAll());}if($action==='categories'){ok($pdo->query('SELECT * FROM categories ORDER BY sort_order,created_at DESC')->fetchAll());}fail('Unknown admin action',404);}catch(Throwable $e){fail('Server error',500);}
